#!/usr/bin/env python3
"""Build topic/result routes from completed-PDF extracts and explicit placeholders."""
import json
from html import escape as e
from pathlib import Path
from site_components import ROOT, merchandise
CONFIG=json.loads((ROOT/'data/numerology-topics.json').read_text())
READINGS=json.loads((ROOT/'data/numerology-profiles.json').read_text())['topics']
TOPICS=CONFIG['topics'];STANDARD=CONFIG['standard_routes'];OUT=ROOT/'numerology'

def page(title,description,body,depth=1,interactive=False,indexable=True):
    p='../'*depth;home=p+'numerology/index.html'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080b19"><meta name="description" content="{e(description)}">{'' if indexable else '<meta name="robots" content="noindex,follow">'}<title>{e(title)} | Crystaleye</title><link rel="icon" href="{p}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{p}assets/site.css"><link rel="stylesheet" href="{p}numerology/numerology.css"><link rel="stylesheet" href="{p}assets/merchandise.css"><link rel="stylesheet" href="{p}assets/cyberpunk.css"><script src="{p}assets/site.js" defer></script>{'<script type="module" src="numerology.js"></script>' if interactive else ''}</head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="{p}index.html" aria-label="Crystaleye home"><svg class="brand-mark" viewBox="0 0 48 32" aria-hidden="true"><path d="M2 16Q24-10 46 16Q24 42 2 16Z"/><path d="m24 5 9 11-9 11-9-11Z"/><circle cx="24" cy="16" r="3"/></svg><span>crystaleye<span class="brand-dot">.</span></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav"><span>Menu</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 6h14M3 14h14"/></svg></button><nav id="site-nav" aria-label="Main navigation"><a href="{home}">Numerology</a><a href="{home}#numbers">The 21 numbers</a><a href="{p}astrology/index.html">Astrology</a></nav><a class="header-cta" href="{home}#calculator">Start with your three →</a></header><main id="main">{body}{merchandise(p)}</main><footer class="site-footer wrap num-footer"><a class="brand" href="{p}index.html">crystaleye<span class="brand-dot">.</span></a><nav aria-label="Footer"><a href="{home}">Numerology home</a><a href="{p}numerology-calculator/index.html">Full calculator</a><a href="{p}numerology/report.html">The full report</a><a href="{p}tarot/index.html">Tarot</a><a href="{p}shop/index.html">Books &amp; decks</a></nav><p>Numerology is a symbolic tradition for reflection, not a scientifically validated assessment or prediction method. Different schools use different calculation conventions; a number does not determine your worth or future.</p></footer></body></html>'''

def report_offer(prefix=''):
    r=CONFIG['report']
    return f'''<section class="num-report"><div><p class="eyebrow">A fuller picture, at your pace</p><h2>Your numbers.<br>Your <em>whole story.</em></h2><p>The planned Full Numerology report brings your 21 chart positions together in one expanded reading. The remaining guide content and ordering details are still being prepared.</p></div><div><h3>{r['name']}</h3><p class="report-price">${r['price']} <span>CAD · one-time purchase</span></p><p class="num-status">Coming soon · ordering is not open</p><a class="button button-gold" href="{prefix}report.html">Explore the full report →</a><p class="fine-print">No payment, email address, or personal details are collected here.</p></div></section>'''

def badge(t):return 'Guide available' if t['slug'] in READINGS else 'Profiles coming soon'

def number_label(t,n):
    if n in [11,22,33] and t['slug'] not in ['birthday','karmic-lessons','hidden-passion','balance'] and 'challenge' not in t['slug']:return f'{n}/{ {11:2,22:4,33:6}[n]}'
    return str(n)

def grid_numbers(t,extra=False):
    values=([0] if t['group']=='Challenges' else [])+STANDARD
    if t['slug']=='birthday':values+= [n for n in range(1,32) if n not in values]
    if extra: values=[n for n in values if n not in STANDARD]
    elif t['slug']=='birthday':values=STANDARD
    tiles=[]
    for n in values:
        ready=str(n) in READINGS.get(t['slug'],{}).get('profiles',{})
        alias=t['slug']=='balance' and n in [11,22,33]
        label='Read the profile' if ready else ('Guide cross-reference' if alias else ('Profile coming soon' if n in t['valid_results'] else 'Range & convention note'))
        tiles.append(f'<a class="number-tile" href="number-{n}/"><span>{number_label(t,n)}</span><small>{label}</small></a>')
    return '<div class="number-grid">'+''.join(tiles)+'</div>'

def hub():
    groups=list(dict.fromkeys(t['group'] for t in TOPICS))
    cards=''.join(f'''<article class="topic-card" data-group="{e(t['group'])}" data-search="{e(t['name'].lower())}"><p class="eyebrow">{t['group']}</p><h3><a href="{t['slug']}/">{e(t['name'])} →</a></h3><p>{e(t['overview'])}</p><span class="topic-state {'is-ready' if t['slug'] in READINGS else ''}">{badge(t)}</span></article>''' for t in TOPICS)
    body=f'''<section class="wrap num-hero"><div><p class="eyebrow"><span class="tiny-star" aria-hidden="true">✧</span> The numerology wing</p><h1>Your name.<br>Your birthday.<br><em>A different angle.</em></h1><p class="section-copy">Start with three numbers. Get curious about the patterns. Explore the stories attached to them, without handing over the authorship of your own life.</p><div class="hero-actions"><a class="button button-gold" href="#calculator">Find my three numbers →</a><a class="text-link" href="#what-is-numerology">New to numerology? Start here →</a></div></div><div class="number-orbit" aria-hidden="true"><div class="orbit-circle circle-one"></div><div class="orbit-circle circle-two"></div><div class="orbit-core"><span>1 · 2 · 3</span><strong>YOUR<br>NUMBERS</strong><small>11 / 22 / 33</small></div>{''.join(f'<span class="orbit-digit digit-{i}">{i}</span>' for i in range(1,10))}</div></section>
<section class="wrap num-section" id="what-is-numerology"><div class="num-topline"><p class="eyebrow">01 / A little context</p><span>Numbers as a language for reflection</span></div><h2>What is <em>numerology?</em></h2><div class="num-explainer"><article><h3>A symbolic reading of names and dates.</h3><p>Numerology assigns meanings to numbers and uses conventions to derive them from information such as a name or birth date. In the Western name-based system used here, letters repeat through values 1–9. A date is broken into components and reduced according to the chart position.</p><p>Different numbers ask different questions: Personality concerns outward impression, Life Path concerns development, and Destiny or Expression concerns contribution. These are interpretive themes, rather than scientific measurements of who you are.</p></article><article><h3>How old is it?</h3><p>Number symbolism has roots stretching back thousands of years. Greek Pythagorean traditions developed around the sixth and fifth centuries BCE—roughly 2,500 years ago—and linked numbers with patterns, harmony, and ideas about the world.</p><p>Today’s name-and-birth-date systems developed through later traditions and vary between schools. There is no single founding date for every practice called numerology. The age of number symbolism does not establish that a present-day reading can predict events.</p><a class="text-link" href="https://plato.stanford.edu/entries/pythagoras/" target="_blank" rel="noopener noreferrer">Historical context: Pythagoras →</a></article></div></section>
<section class="num-calculator-band num-section" id="calculator"><div class="wrap"><div class="num-topline"><p class="eyebrow">02 / Start small</p><span>Three results. A simple beginning.</span></div><h2>A little detail.<br><em>Your first three numbers.</em></h2><p class="section-copy">Enter the full name on your birth record and your date of birth. Your details stay in this tab; they are not saved or sent anywhere.</p><div class="mini-layout"><form id="mini-form" class="mini-form"><label for="birth-name">Full name at birth</label><input id="birth-name" name="birthName" autocomplete="off" maxlength="240" required placeholder="First, middle, and last names"><p class="fine-print">Use all name words. Accented Latin letters, spaces, apostrophes, and hyphens are supported. A–Z letter values are used; Y counts as a consonant.</p><label for="birth-date">Date of birth</label><input id="birth-date" name="birthDate" type="date" min="1800-01-01" max="2026-12-31" required><p class="fine-print">Uses the full calculator’s supported birth years, 1800–2026.</p><p id="mini-error" class="mini-error" role="alert"></p><button class="button button-gold" type="submit" id="mini-submit" disabled>Enable JavaScript to calculate</button><button class="mini-clear" type="reset">Clear my details</button><noscript><p class="notice">Enable JavaScript to use the quick calculator. The topic guides and number profiles work without it.</p></noscript></form><div class="mini-output" id="mini-output" aria-live="polite" aria-atomic="true"><p class="eyebrow">A first look at your chart</p><h3>Three ways<br>to get <em>curious.</em></h3><ul><li><strong>Personality</strong><span>Your outward impression</span></li><li><strong>Life Path</strong><span>A theme for development</span></li><li><strong>Destiny</strong><span>A lens on contribution</span></li></ul></div></div><div class="quick-conventions"><details><summary>How are these three numbers calculated?</summary><p>Personality uses consonants in each birth-name word, reduced word by word and then combined. Life Path reduces the month, day, and year separately and then combines them. This quick calculator uses the existing app’s Destiny rule: reduce Personality + Soul’s Desire, with Soul’s Desire calculated from the vowels. It preserves 11, 22, and 33 at completed reduction steps.</p><p>The completed Expression guide instead reduces the totals of all letters in each name word. That can change a master-number result. Your calculation details identify the difference when it occurs.</p></details><a class="text-link" href="../numerology-calculator/index.html">Want all 21 positions? Open the full calculator →</a></div></div></section>
<section class="wrap num-section" id="numbers"><div class="num-topline"><p class="eyebrow">03 / The chart library</p><span>21 positions. Different questions.</span></div><h2>Find the number.<br><em>Follow the thread.</em></h2><p class="section-copy">Each topic explains what it represents and how it is calculated. Seven completed guides supply the profiles available now; the other result pages are clearly marked as coming soon.</p><div class="topic-controls" id="topic-controls" hidden><label class="topic-search">Find a topic<input id="topic-search" type="search" placeholder="Try “personality” or “third”"></label><div class="topic-filters" aria-label="Filter number topics">{''.join(f'<button type="button" data-group-filter="{e(g)}" aria-pressed="{str(g=="All").lower()}">{g}</button>' for g in ['All']+groups)}</div></div><p class="fine-print" id="topic-count" aria-live="polite">21 topics</p><div class="topic-grid">{cards}</div><p class="topic-empty notice" id="topic-empty" hidden>No topics match. Try another search or choose All.</p></section><div class="wrap num-section">{report_offer()}</div>'''
    return page('Numerology — Your first three numbers & the 21-number library','What numerology means, its historical roots, a simple Personality/Life Path/Destiny calculator, 21 topic libraries, and the upcoming $19.99 CAD report.',body,interactive=True)

def topic_page(t):
    slug=t['slug'];guide=READINGS.get(slug);source=f'<a class="button button-outline" href="../../{guide["pdf"]}">Read the completed PDF guide →</a>' if guide else '<p class="num-status">Detailed profiles coming soon · guide not yet complete</p>'
    extra=''
    if slug=='birthday':extra='<h3 class="extra-heading">More calendar-day values</h3><p class="section-copy">Birthday keeps the unreduced day, so 10 and 12–31 also need their own routes. The 11 and 22 pages appear in the main grid above.</p>'+grid_numbers(t,True)
    body=f'''<div class="wrap num-breadcrumb"><a href="../index.html">Numerology</a><span>/</span><span>{e(t['name'])}</span></div><section class="wrap topic-hero"><div><p class="eyebrow">{t['group']} / {badge(t)}</p><h1>{e(t['name'])}<em> number.</em></h1><p class="section-copy">{e(t['overview'])}</p><div class="hero-actions"><a class="button button-gold" href="#results">Find your result →</a><a class="text-link" href="#calculation">How it is calculated →</a></div></div><div class="topic-sigil" aria-hidden="true"><span>{'A–Z' if t['group'] in ['Core numbers','Current name','Name patterns'] and slug not in ['life-path','birthday'] else 'M · D · Y'}</span><strong>{str(len(guide['profiles'])) if guide else '···'}</strong><small>{'INTERPRETATIONS' if guide else 'EXPLORE THE PATTERN'}</small></div></section><section class="wrap method-layout" id="calculation"><div><p class="eyebrow">What this number tells you</p><h2>A different <em>lens.</em></h2><p>{e(t['overview'])}</p>{source}</div><div class="method-box"><p class="eyebrow">How it is calculated</p><ol>{''.join('<li>'+e(s)+'</li>' for s in t['steps'])}</ol><details open><summary>Conventions worth knowing</summary><p>{e(t['convention_note'])}</p></details></div></section><section class="wrap num-section" id="results"><div class="num-topline"><p class="eyebrow">Explore this position</p><span>Read the status beneath each number</span></div><h2>Your result.<br><em>Its own context.</em></h2><p class="section-copy">The twelve requested number routes appear below. A convention note identifies values this position does not produce. Unfinished interpretations remain placeholders, rather than general meanings borrowed from a different chart position.</p>{grid_numbers(t)}{extra}{'<p class="notice">No missing values means no selected Karmic Lessons. It is an empty set, not Lesson 0 or proof that development is complete.</p>' if slug=='karmic-lessons' else ''}</section><div class="wrap num-section">{report_offer('../')}</div>'''
    return page(t['name']+' — Meaning, calculation & result library',t['overview'],body,2)

def reserved_note(t,n):
    slug=t['slug']
    if slug=='birthday':return 'There is no thirty-third calendar day. This project keeps Birthday as the original day, 1–31, so Birthday 33 is not a possible result.'
    if slug in ['karmic-lessons','hidden-passion']:return f'{t["name"]} works with letter-value categories 1–9. It can return several values, but they are not added together or renamed as master 11, 22, or 33.'
    if t['group']=='Challenges':return 'This is a reserved convention page, not a published master Challenge profile. Standard fully reduced Challenge methods use 0–9. Crystaleye’s custom master-preserving, zero-clamped subtraction can produce different unreduced outputs; its formula is explained on the topic page. A researched interpretation for this value is not available.'
    if slug=='first-life-cycle':return f'The First Life Cycle uses the birth month. Under this app’s reduction rule, months can yield 1–9 or 11, so {n} is not produced by this position.'
    if slug=='second-life-cycle':return f'The Second Life Cycle uses a calendar day from 1–31. With the stated reduction rule, that can yield 1–9, 11, or 22; it cannot yield {n}.'
    return f'Within the current 1800–2026 birth-year range, this year-based position does not produce {n} under the stated reduction rule. This route preserves the requested library structure and explains the range.'

def result_page(t,n):
    slug=t['slug'];guide=READINGS.get(slug);profile=guide and guide['profiles'].get(str(n));alias=slug=='balance' and n in [11,22,33];valid=n in t['valid_results'];label=number_label(t,n)
    if profile:
        status='From the completed guide';title=profile['subtitle'];paras=''.join(f'<section class="reading-part"><h2>{heading}</h2><p>{e(text)}</p></section>' for heading,text in zip(['The central theme','A possible tension','A constructive direction'],profile['paragraphs']))
        sources=''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["title"])}</a>{"<p>"+e(s["role"])+"</p>" if s.get("role") else ""}</li>' for s in profile['sources'])
        content=f'''<div class="profile-prose">{paras}<details class="profile-evidence"><summary>Guide provenance and interpretation notes</summary><p>{e(profile['evidence_note'])}</p><p>This reading is copied from the completed {e(t['name'])} guide, page {profile['pdf_page']}. The final paragraph is constructive editorial synthesis. It is not a new forecast or a claim about your abilities or future.</p><a class="text-link" href="../../../{guide['pdf']}#page={profile['pdf_page']}">Open this page in the PDF →</a>{'<ul>'+sources+'</ul>' if sources else '<p>The PDF bibliography records the source references used in this profile.</p>'}</details></div>'''
    elif alias:
        root={11:2,22:4,33:6}[n];status='Guide cross-reference';title=f'For app Balance {n}, read guide {root}.'
        content=f'''<section class="placeholder-panel"><p class="eyebrow">A calculation difference, explained</p><h2>One position.<br><em>Two reduction conventions.</em></h2><p>The full calculator keeps a Balance total of {n}. The completed guide reduces Balance fully, so {n} becomes {root}. It does not provide a separate Balance {n} personality or master profile.</p><p>Use the completed Balance {root} reading for the guide’s selected method. Your original app result has not been changed.</p><a class="button button-gold" href="../number-{root}/">Read Balance {root} →</a></section>'''
    elif valid:
        status='Profile coming soon';title='This specific reading is still to come.'
        content=f'''<section class="placeholder-panel"><p class="eyebrow">A clearly marked placeholder</p><h2>A place for the<br><em>next chapter.</em></h2><p>A completed {e(t['name'])} {n} interpretation has not been published in this series yet. This page reserves its route; it does not substitute a general number-{n} meaning or material from an unfinished research draft.</p><p>{e(t['overview'])}</p><a class="button button-outline" href="../#calculation">Understand this position’s calculation →</a></section>'''
    else:
        status='Range & convention note';title='Check the position before the meaning.'
        content=f'''<section class="placeholder-panel"><p class="eyebrow">A reserved route</p><h2>The same numeral<br><em>has different rules.</em></h2><p>{e(reserved_note(t,n))}</p><a class="button button-outline" href="../#results">Return to the valid-result notes →</a></section>'''
    body=f'''<div class="wrap num-breadcrumb"><a href="../../index.html">Numerology</a><span>/</span><a href="../">{e(t['name'])}</a><span>/</span><span>{n}</span></div><section class="wrap result-hero"><div><p class="eyebrow">{e(t['name'])} / {status}</p><h1>{e(t['name'])}<br><em>{label}.</em></h1><p class="result-subtitle">{e(title)}</p></div><div class="result-sigil" aria-hidden="true">{n}</div></section><div class="wrap result-layout"><aside><p class="eyebrow">Keep the context</p><p>{e(t['overview'])}</p><a href="../#calculation">How this number is calculated →</a><a href="../#results">All {e(t['name'])} results →</a><a href="../../index.html#calculator">Try the quick calculator →</a>{'<a href="../../../'+guide['pdf']+'">The complete PDF guide →</a>' if guide else '<span class="fine-print">Topic guide in preparation</span>'}</aside>{content}</div><section class="wrap result-next"><p class="eyebrow">Keep exploring this position</p><nav aria-label="Other {e(t['name'])} results">{''.join(f'<a href="../number-{x}/" {"aria-current=\"page\"" if x==n else ""}>{x}</a>' for x in (([0] if t['group']=='Challenges' else [])+STANDARD))}</nav></section>'''
    return page(f'{t["name"]} {label} — {title}',f'{t["name"]} {n}: {status.lower()}. '+t['overview'],body,3,indexable=bool(profile))

def report():
    r=CONFIG['report'];body=f'''<section class="wrap report-hero"><p class="eyebrow">Your full chart, thoughtfully explained</p><h1>More than<br><em>three numbers.</em></h1><p class="section-copy">The planned {r['name']} brings together the 21 positions in your chart, giving each number its own context and explaining how the positions differ.</p><p class="report-price">${r['price']} <span>CAD · one-time purchase</span></p><p class="num-status">Coming soon · no orders or payments are being accepted</p><a class="button button-gold" href="index.html#calculator">Start with your free three numbers →</a></section><section class="wrap report-details"><div><p class="eyebrow">The planned reading</p><h2>Your chart.<br><em>In context.</em></h2><p>Personality, Soul’s Desire, Life Path, and Destiny; the current-name Minor numbers; Balance, Karmic Lessons, Hidden Passion, and Birthday; three Life Cycles, four Pinnacles, and four Challenges. Set-valued results stay as sets, and calculation conventions will be identified.</p><p>The result library is being built from the completed research guides. Remaining profiles are still placeholders, so a finished paid report is not being offered for immediate delivery.</p></div><div class="method-box"><h3>Before ordering opens</h3><p>Delivery format, final contents, checkout terms, and secure payment will be provided before sales begin. This page collects no name, birth date, email address, or payment information.</p><p>The full calculator remains free to use if you want to see all 21 values now. The planned paid report adds an expanded reading, rather than another set of calculations.</p><a class="text-link" href="../numerology-calculator/index.html">Open the full calculator →</a><a class="text-link" href="index.html#numbers">Explore the available guides →</a></div></section>'''
    return page(r['name']+' — $'+r['price']+' CAD, coming soon','Explore the planned one-time $19.99 CAD full numerology report for all 21 chart positions. Ordering is not yet open.',body)

def main():
    OUT.mkdir(exist_ok=True);(OUT/'index.html').write_text(hub());(OUT/'report.html').write_text(report());count=0
    for t in TOPICS:
        folder=OUT/t['slug'];folder.mkdir(exist_ok=True);(folder/'index.html').write_text(topic_page(t))
        values=([0] if t['group']=='Challenges' else [])+STANDARD
        if t['slug']=='birthday':values+= [n for n in range(1,32) if n not in values]
        for n in values:
            dest=folder/f'number-{n}';dest.mkdir(exist_ok=True);(dest/'index.html').write_text(result_page(t,n));count+=1
    print(f'Built numerology hub, report offer, {len(TOPICS)} topic pages, and {count} result routes.')

if __name__=='__main__':main()
